<template>
  <div>
    <div class="header flex-space-between">
      <!-- 'ty-lite', 'ty-prod', 'ty-pro-2.0'型号共用  -->
      <div class="left">{{ deviceConfig.title }}</div>
      <div class="right">
        <div
          class="battery-icon"
          :style="{ borderColor: batteryColor, color: batteryColor }"
        >
          <div class="battery-body">
            <div class="battery-level" :style="batteryLevelStyle"></div>
          </div>
          <div class="battery-tip"></div>
        </div>
        <div class="percentage-container">
          <span>{{ batteryText }}</span>
        </div>
      </div>
    </div>

    <!-- 状态图例 -->
    <div class="status-legend">
      <div
        class="legend-item"
        v-for="(status, key) in STATUS_CONFIG"
        :key="key"
      >
        <div
          class="status-indicator"
          :style="{ backgroundColor: status.color }"
        ></div>
        <span>{{ status.label }}</span>
      </div>
    </div>

    <div class="bottom flex-space-between">
      <!-- 左侧设备组 -->
      <DeviceGroup :groups="deviceGroups.leftGroups" />
      <!-- 中间图片 -->
      <div class="pic">
        <img :src="deviceConfig.image" :alt="deviceConfig.title" />
      </div>
      <!-- 右侧设备组 -->
      <DeviceGroup :groups="deviceGroups.rightGroups" />
    </div>
  </div>
</template>

<script setup>
import { computed, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { useWslStore } from '@/store/modules/ws.js'
import proto from '@/utils/sdkapi_pb.js'
import { useVersionStore } from '@/store/modules/version'

import { STATUS_CONFIG } from '@/constants/status'
import { getTyDeviceGroups, groupDevicesByGroup } from './const'
import DeviceGroup from './deviceGroup.vue'

// 版本确定
const versionStore = useVersionStore()
console.log('天轶currentVersion',versionStore.currentVersion)

const store = useWslStore()
const { received, isConnected } = storeToRefs(store)

// 标题和图片配置
const deviceConfig = computed(() => getTyDeviceGroups(versionStore.currentVersion))

// 监听连接状态
watch(
  () => isConnected.value,
  (newStatus) => {
    if (newStatus) {
      // 当连接成功时发送命令13
      const request = new proto.Request()
      request.setCommand(proto.Command.CMD_GET_STATUS_DATA)
      const data = request.serializeBinary()
      store.websocketSendData({ data })
    }
  },
  { immediate: true }
)

// 合并多个数组（手臂、腰部 等数据不在同一个数组字段中，合并哪一个需要根据具体型号分析）
  const allDevices = computed(() =>{
    const statusData = received.value?.statusData || {}
    // 数据：电源板、地盘、遥控 三个特殊处理(默认取数组第一项)
    const powerDataList = statusData.powerDataList?.length > 0 ? [
    {
      ...statusData.powerDataList?.[0] || {},  
      devdesp: '电源',
      group: '电源板',
      status: statusData?.powerDataList?.[0]?.status,
    }] : []
    const switchDataList = statusData.switchDataList?.length > 0 ? [
    {
      ...statusData.switchDataList?.[0] || {},  
      devdesp: '急停开关',
      group: '电源板',
      status: statusData?.switchDataList?.[0]?.status,
    }] : []
    const remoteControlDataList = statusData.remoteControlDataList?.length > 0 ? [
    {
      ...statusData.remoteControlDataList?.[0] || {},  
      group: '遥控',
      devdesp: '遥控',
      status: statusData?.remoteControlDataList?.[0]?.status,
    }] : []
    return [
      ...(statusData.motorDataList || []),
      ...(statusData.sixDofDataList || []),
      ...(statusData.handDataList || []),

      ...switchDataList,
      ...powerDataList,
      ...remoteControlDataList,
    ]
  })

// 智能分组展示（左右）
const deviceGroups = computed(() => groupDevicesByGroup(
  allDevices.value, 
  ['头部','右','手部', '电源板'],
  ['颈部', '左', '下肢', '底盘'],
  ['头部', '右肩', '右臂','手部', '电源板'],
  ['颈部', '左肩', '左臂', '下肢', '底盘'],
  'left'))
console.log('智能分组结果', deviceGroups.value?.leftGroups, deviceGroups.value?.rightGroups)

// 电池相关计算属性
const batteryPercentage = computed(() => {
  const batteryLevel =
    received.value?.statusData?.powerDataList?.[0]?.batteryLevel
  return batteryLevel !== undefined && batteryLevel !== null
    ? Number(batteryLevel).toFixed(2) // 保留两位小数，确保转换为数字
    : null
})

const batteryColor = computed(() => {
  if (batteryPercentage.value === null) return '#B0B0B0'
  return batteryPercentage.value > 20 ? '#27FF23' : '#FF0000'
})

const batteryLevelStyle = computed(() => ({
  width:
    batteryPercentage.value === null ? '100%' : `${batteryPercentage.value}%`,
  backgroundColor: batteryColor.value
}))

const batteryText = computed(() =>
  batteryPercentage.value === null ? '？%' : `${batteryPercentage.value}%`
)
</script>

